  `title` = 'Tentang Kami',
  `content` = '[{\"type\":\"hero\",\"data\":{\"slider_duration\":5000,\"banners\":[{\"title\":\"Produsen Resmi Roster Beton Arsitektural & Bata Expose\",\"subtitle\":\"Berangkat dari warisan keahlian pengrajin cetak beton di sentra Plered Purwakarta, IndoRoster hadir memberikan kemudahan akses material arsitektur berkualitas harga pabrik bagi masyarakat Indonesia.\",\"badge\":\"🏛️ Profil & Legalitas Pabrik\",\"image\":\"https://res.cloudinary.com/indoroster/image/upload/v1765259970/7_blkgfx.jpg\",\"button_text\":\"Hubungi Tim Sales\",\"button_url\":\"https://wa.me/6281389709847\",\"button_2_text\":\"Lihat Galeri Proyek\",\"button_2_url\":\"/gallery\",\"alignment\":\"left\",\"image_opacity\":40,\"overlay_color\":\"#020617\",\"overlay_opacity\":80}]}},{\"type\":\"ticker\",\"data\":{\"bg_theme\":\"dark\",\"speed\":\"normal\",\"text\":\"🏛️ Produsen Terpercaya Plered Purwakarta · 📦 5000+ Proyek Sukses · 🛡️ Garansi Pecah 100% · 📑 Dokumen SPK & Faktur Pajak Resmi · 🚚 Jangkauan Kirim Nasional\"}},{\"type\":\"why_us\",\"data\":{\"badge\":\"💎 Nilai Utama Kami\",\"title\":\"Komitmen Kualitas & Transparansi Tanpa Perantara\",\"description\":\"Kami percaya bahwa setiap hunian dan bangunan komersial berhak mendapatkan material arsitektur terbaik dengan harga yang adil dan garansi keamanan penuh.\",\"bg_theme\":\"slate\",\"items\":[{\"title\":\"Integritas Mutu Material\",\"description\":\"Kami menjaga konsistensi formula beton padat mutu K-200 agar kokoh, berumur panjang, dan tahan terhadap cuaca tropis ekstrem.\"},{\"title\":\"Harga Pabrik yang Transparan\",\"description\":\"Tanpa biaya markup perantara, memberikan keuntungan maksimal bagi pemilik rumah dan fleksibilitas margin bagi kontraktor.\"},{\"title\":\"Layanan Logistik & Tanggung Jawab 100%\",\"description\":\"Kami menjamin setiap keping barang yang dikirim sampai dengan aman. Klaim ganti baru dilayani dengan mudah tanpa birokrasi berbelit.\"}]}},{\"type\":\"document_procurement_proof\",\"data\":{\"badge\":\"📑 Administrasi & Legalitas Sah\",\"title\":\"Kesiapan Administrasi Resmi & Faktur Pajak\",\"subtitle\":\"Kelengkapan dokumen Surat Jalan resmi, Faktur Pajak PPN/PPh, dan SPK untuk kemudahan administrasi Anda.\",\"bg_theme\":\"white\"}},{\"type\":\"partner_cta\",\"data\":{\"badge\":\"Kemitraan Terpercaya\",\"title\":\"Siap Bermitra dengan Pabrik IndoRoster?\",\"description\":\"Dapatkan penawaran harga terbaik dan konsultasi motif fasad gratis dari tim ahli kami.\",\"bg_theme\":\"terra\",\"cta_text_1\":\"Hubungi via WhatsApp\",\"cta_url_1\":\"https://wa.me/6281389709847\",\"cta_text_2\":\"Lihat Katalog Produk\",\"cta_url_2\":\"/katalog\"}}]',
  `meta_title` = 'Tentang IndoRoster — Pabrik Produsen Roster Beton & Bata Expose Plered Purwakarta',
  `meta_description` = 'Profil resmi IndoRoster, produsen tangan pertama roster beton minimalis, bata expose, dan ornamen dinding arsitektural berbasis di sentra pengrajin Plered Purwakarta melayani pengiriman seluruh Indonesia.',
  `is_active` = 1,
