rra\",\"cta_text_1\":\"Chat WhatsApp Sales\",\"cta_url_1\":\"https://wa.me/6281389709847\",\"cta_text_2\":\"Lihat Katalog Produk\",\"cta_url_2\":\"/katalog\"}},{\"type\":\"contact_form\",\"data\":{\"badge\":\"HUBUNGI PABRIK LANGSUNG\",\"title\":\"Hubungi Pabrik & Konsultasi Proyek\",\"subtitle\":\"Solusi roster beton minimalis berkualitas tinggi dari sentra Plered Purwakarta. Hubungi kami untuk konsultasi motif, RAB, sampel material, dan pengiriman ke seluruh Indonesia.\",\"alignment\":\"left\",\"bg_theme\":\"white\"}}]',
