UPDATE `pages` SET 
  `title` = 'Proses Produksi Pabrik',
  `content` = '[{\"type\":\"hero\",\"data\":{\"slider_duration\":5000,\"banners\":[{\"title\":\"Standar Pabrikasi Roster Beton Cetak Tumbuk K-200\",\"subtitle\":\"Melihat langsung dapur produksi IndoRoster di sentra Plered Purwakarta: formula agregat pasir silika terpilih, pemadatan hidrolik mekanis, dan kontrol mutu presisi sudut 90° sebelum dikirim ke proyek Anda.\",\"badge\":\"⚙️ Standar Pabrikasi & QC Ketat\",\"image\":\"https://res.cloudinary.com/indoroster/image/upload/v1765262980/2_zurmam.jpg\",\"button_text\":\"Konsultasi Spesifikasi Teknis\",\"button_url\":\"https://wa.me/6281389709847\",\"button_2_text\":\"Lihat Katalog Produk\",\"button_2_url\":\"/katalog\",\"alignment\":\"left\",\"image_opacity\":40,\"overlay_color\":\"#020617\",\"overlay_opacity\":80}]}},{\"type\":\"ticker\",\"data\":{\"bg_theme\":\"dark\",\"speed\":\"normal\",\"text\":\"⚙️ Formula Mutu K-200 · 📐 Akurasi Sudut 90° Presisi · 🏭 Sentra Pabrikasi Plered Purwakarta · 🛡️ Garansi Pecah Ganti Baru 100% · 🚚 Truk Logistik Siap Kirim Tiap Hari\"}},{\"type\":\"why_us\",\"data\":{\"badge\":\"🏭 4 Tahapan Kontrol Kualitas Pabrik\",\"title\":\"Bagaimana Roster Beton Berkualitas Dibuat?\",\"description\":\"Kami tidak menggunakan metode cor basah manual yang rentan keropos. Setiap keping melewati 4 tahap manufaktur presisi.\",\"bg_theme\":\"slate\",\"items\":[{\"title\":\"1. Seleksi Agregat Pasir Silika & Semen Berkualitas\",\"description\":\"Pencampuran pasir silika gradasi khusus dengan semen Portland murni mutu K-200 untuk kekuatan ikatan maksimal.\"},{\"title\":\"2. Pemadatan Hidrolik Cetak Tumbuk Mekanis\",\"description\":\"Proses press tumbuk padat dengan tekanan hidrolik tinggi untuk menghilangkan rongga udara di dalam adukan semen.\"},{\"title\":\"3. Curing & Pengeringan Alami Bebas Retak\",\"description\":\"Proses hidrasi pengeringan bertahap dengan kelembaban terkontrol agar beton matang sempurna dan tidak rapuh.\"},{\"title\":\"4. Kalibrasi Sudut 90° & Quality Check Akhir\",\"description\":\"Pemeriksaan dimensi tiap keping agar sudut siku sempurna 90° sehingga tukang bangunan dapat memasang nat dengan rapi dan cepat.\"}]}},{\"type\":\"strength_test\",\"data\":{\"badge\":\"💪 Uji Ketahanan Beban\",\"title\":\"Uji Kekuatan Beton Cetak Tumbuk Padat\",\"subtitle\":\"Kepadatan tinggi menjamin keping roster kuat menahan benturan dan tidak mudah rompal saat bongkar muat di lokasi proyek Anda.\",\"bg_theme\":\"dark\"}},{\"type\":\"ugc_videos\",\"data\":{\"badge\":\"🎬 Dokumentasi Lapangan\",\"title\":\"Video Dokumentasi Proses Manufaktur & Pemuatan\",\"subtitle\":\"Simak video dokumentasi aktivitas para pengrajin ahli kami di pabrik Plered Purwakarta.\",\"bg_theme\":\"white\"}},{\"type\":\"faq\",\"data\":{\"badge\":\"❓ FAQ Manufaktur & Teknis\",\"title\":\"Pertanyaan Teknis Seputar Produksi Roster\",\"subtitle\":\"Penjelasan mengenai mutu beton K-200, berat per keping (~4-4.5 kg), finishing permukaan halus abu/putih, dan estimasi waktu produksi partai besar.\",\"bg_theme\":\"white\"}},{\"type\":\"partner_cta\",\"data\":{\"badge\":\"Kemitraan Pabrik & Pengadaan Proyek\",\"title\":\"Terkoneksi Langsung dengan Pabrik Roster IndoRoster\",\"description\":\"Solusi pengadaan roster beton arsitektural tangan pertama untuk pemilik rumah, kontraktor, arsitek, pemilik bisnis kafe, hingga developer kawasan perumahan di seluruh Indonesia.\",\"bg_theme\":\"terra\",\"cta_text_1\":\"Konsultasi Pengadaan via WhatsApp\",\"cta_url_1\":\"https://wa.me/6281389709847\",\"cta_text_2\":\"Lihat Katalog Produk\",\"cta_url_2\":\"/katalog\"}}]',
  `meta_title` = 'Proses Produksi Roster Beton Cetak Padat Presisi K-200 — IndoRoster Plered Purwakarta',
  `meta_description` = 'Melihat langsung standar manufaktur roster beton IndoRoster: pemilihan agregat pasir silika, pemadatan hidrolik mutu K-200, pengeringan alami, dan kontrol presisi siku 90° di Plered Purwakarta.',
  `is_active` = 1,
  `updated_at` = NOW()
WHERE `slug` = 'proses-produksi';

UPDATE `pages` SET 
  `title` = 'Syarat & Ketentuan',
  `content` = '[{\"type\":\"rich_text\",\"data\":{\"title\":\"Syarat & Ketentuan Layanan\",\"content\":\"<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-6\\\">\\n    Selamat datang di <strong>INDOROSTER</strong> (<em>indoroster.com</em>). Syarat dan Ketentuan ini mengatur penggunaan situs web, pemesanan produk roster arsitektural beton, proses transaksi pembayaran melalui gerbang pembayaran <strong>Midtrans</strong>, hingga layanan pengiriman dan klaim garansi.\\n</p>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-6\\\">\\n    Dengan mengakses situs ini, mendaftarkan akun, atau melakukan pemesanan, Anda menyatakan telah membaca, memahami, dan menyetujui untuk terikat dengan seluruh Syarat &amp; Ketentuan di bawah ini. Jika Anda tidak menyetujui salah satu bagian dari ketentuan ini, mohon untuk tidak melanjutkan penggunaan situs atau layanan kami.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">1. Ketentuan Penggunaan (Conditions of Use &amp; Overview)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Layanan situs web INDOROSTER disediakan untuk Anda dengan syarat penerimaan penuh tanpa modifikasi atas syarat, ketentuan, dan pemberitahuan yang tercantum di sini. Penggunaan situs ini merupakan bentuk persetujuan hukum yang mengikat antara Anda sebagai Pelanggan dan INDOROSTER sebagai Penyedia Produk &amp; Layanan.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">2. Perubahan Ketentuan &amp; Koreksi Informasi (Modifications &amp; Price Errors)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    INDOROSTER berhak untuk memperbarui, mengubah, atau menyesuaikan Syarat dan Ketentuan, harga produk, deskripsi material, serta ketersediaan stok kapan saja tanpa pemberitahuan sebelumnya.\\n</p>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Apabila terdapat kesalahan ketik teknis atau kekeliruan sistem mengenai harga atau ketersediaan barang pada saat pemesanan dibuat, INDOROSTER berhak untuk mengoreksi pesanan atau menolak/membatalkan pesanan tersebut dan mengembalikan dana penuh yang telah dibayarkan oleh Pelanggan.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">3. Hak Cipta &amp; Kekayaan Intelektual (Copyrights)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Seluruh materi dalam situs web ini — termasuk namun tidak terbatas pada merek/logo INDOROSTER, foto produk asli pabrik, desain roster arsitektural, grafis, teks, video dokumentasi produksi, dan perangkat lunak — adalah milik eksklusif INDOROSTER dan dilindungi oleh Undang-Undang Hak Cipta Republik Indonesia serta peraturan kekayaan intelektual internasional. Dilarang keras menyalin, memperbanyak, memodifikasi, mendistribusikan ulang, atau memanfaatkan konten situs ini tanpa izin tertulis dari INDOROSTER.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">4. Pendaftaran Akun &amp; Keamanan (Sign Up &amp; Security)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Untuk melakukan pemesanan dan pelacakan pesanan secara optimal, pengguna disarankan membuat akun dengan memberikan informasi yang akurat, valid, dan terkini (termasuk alamat pengiriman dan nomor kontak aktif). Anda bertanggung jawab penuh untuk menjaga kerahasiaan kata sandi akun Anda dan atas semua aktivitas yang dilakukan di bawah akun tersebut.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">5. Komunikasi Elektronik (Electronic Communications)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Dengan menggunakan layanan kami, Anda menyetujui bahwa kami dapat berkomunikasi dengan Anda secara elektronik melalui email (<strong>abdulhamid66266@gmail.com</strong>) dan/atau pesan WhatsApp resmi pabrik (<strong>0813-8970-9847</strong>) untuk keperluan konfirmasi pesanan, penerbitan invoice/faktur digital, status pelacakan pengiriman kargo, serta informasi penting seputar pesanan Anda.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">6. Deskripsi &amp; Karakteristik Produk (Product Descriptions)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Kami berusaha semaksimal mungkin menampilkan foto, spesifikasi dimensi (cm), dan varian warna roster seakurat mungkin di layar. Namun demikian, karena produk roster beton dibuat menggunakan formula semen dan agregat pasir alami standar mutu K-200, variasi minor pada gradasi warna alami atau tekstur semen merupakan karakteristik wajar dari produk cetak beton arsitektural.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">7. Harga &amp; Metode Pembayaran (Pricing &amp; Payment Gateway)</h3>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2 mb-4\\\">\\n    <li>Seluruh harga yang tertera di situs menggunakan mata uang resmi <strong>Rupiah (IDR)</strong>.</li>\\n    <li>Transaksi pembayaran diproses secara terenkripsi dan aman melalui <em>Payment Gateway</em> resmi <strong>Midtrans</strong> (PT Midtrans) yang telah berlisensi Bank Indonesia.</li>\\n    <li>Metode pembayaran yang tersedia meliputi: <strong>Virtual Account Bank (BCA, Mandiri, BNI, BRI, Permata), QRIS (GoPay, OVO, Dana, ShopeePay), Transfer Bank, dan Kartu Kredit/Debit</strong>.</li>\\n    <li>Pesanan akan diproses ke tahap verifikasi dan pengemasan/produksi setelah konfirmasi pembayaran berhasil diverifikasi oleh sistem Midtrans secara otomatis (<em>real-time</em>).</li>\\n</ul>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">8. Pengiriman &amp; Pengalihan Risiko (Risk of Loss &amp; Shipping)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Pengiriman material roster dilakukan menggunakan armada logistik resmi pabrik INDOROSTER (untuk area Jabodetabek, Purwakarta, Bandung, dan sekitarnya) atau melalui jasa ekspedisi kargo rekanan terpercaya ke seluruh wilayah Indonesia. Biaya pengiriman dihitung berdasarkan lokasi tujuan dan volume/berat pesanan. Pengalihan risiko barang selama proses pengiriman dijamin sesuai dengan klausul garansi pengiriman IndoRoster.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">9. Ketentuan Pengembalian, Retur &amp; Garansi 100% Pecah (Return &amp; Refund Policy)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    INDOROSTER memberikan <strong>Garansi Penggantian Baru 100%</strong> untuk memastikan kepuasan dan ketenangan berbelanja Anda:\\n</p>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2 mb-4\\\">\\n    <li><strong>Garansi Pecah Pengiriman:</strong> Apabila terdapat unit roster yang mengalami kerusakan, patah, atau pecah saat diterima, kami akan mengganti unit tersebut secara gratis.</li>\\n    <li><strong>Syarat Klaim Retur:</strong> Pelanggan wajib melaporkan kerusakan dalam kurun waktu maksimal <strong>2 x 24 jam</strong> sejak barang tiba di lokasi pengiriman, disertai bukti foto jelas dan/atau video saat pembongkaran serta foto Surat Jalan / Resi penerimaan barang.</li>\\n    <li><strong>Pengembalian Dana (Refund):</strong> Apabila penggantian unit tidak memungkinkan (misal stok khusus habis atau pesanan dibatalkan sesuai ketentuan), pengembalian dana (refund) akan diproses kembali ke rekening atau metode pembayaran asal pembeli melalui sistem Midtrans dalam waktu <strong>3 - 7 hari kerja</strong> sesuai prosedur perbankan.</li>\\n    <li>Barang yang sudah terpasang dengan adukan semen di dinding proyek tidak dapat diklaim sebagai retur pecah pengiriman.</li>\\n</ul>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">10. Pembatalan Pesanan (Order Cancellation)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Pembatalan pesanan hanya dapat dilakukan sebelum barang dimuat ke armada pengiriman. Untuk pesanan custom khusus yang telah memasuki proses cetak/produksi massal, pembatalan sepihak tidak dapat dilakukan. Hubungi Customer Support kami segera jika Anda membutuhkan perubahan jadwal pengiriman.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">11. Pembatasan Tanggung Jawab &amp; Ganti Rugi (Indemnity &amp; Disclaimer)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    INDOROSTER tidak bertanggung jawab atas keterlambatan pengiriman yang disebabkan oleh keadaan kahar (<em>Force Majeure</em>) seperti bencana alam, kerusuhan, blokade jalan, atau gangguan lalu lintas ekstrem di luar kendali wajar. Anda setuju untuk membela, mengganti rugi, dan membebaskan INDOROSTER dari segala bentuk tuntutan pihak ketiga yang timbul akibat penyalahgunaan situs atau pelanggaran Syarat dan Ketentuan oleh Anda.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">12. Hukum yang Berlaku (Applicable Laws)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Syarat dan Ketentuan ini diatur dan ditafsirkan sepenuhnya berdasarkan hukum yang berlaku di <strong>Republik Indonesia</strong>. Setiap sengketa yang timbul akan diselesaikan terlebih dahulu melalui musyawarah untuk mufakat, atau melalui yurisdiksi pengadilan di wilayah hukum Republik Indonesia.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">13. Pertanyaan, Saran &amp; Layanan Pelanggan (Contact &amp; Support)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-3\\\">\\n    Jika Anda memiliki pertanyaan mengenai Syarat &amp; Ketentuan ini atau membutuhkan bantuan transaksi, silakan hubungi kontak resmi kami:\\n</p>\\n<div class=\\\"bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 mb-6 not-prose\\\">\\n    <p class=\\\"font-bold text-slate-900 dark:text-white text-sm mb-3\\\">LOKASI &amp; KONTAK RESMI PABRIK:</p>\\n    <ul class=\\\"space-y-2.5 text-xs sm:text-sm text-slate-700 dark:text-slate-300 font-medium\\\">\\n        <li class=\\\"flex items-start gap-2.5\\\">\\n            <span class=\\\"text-terra-600 dark:text-terra-400 font-bold shrink-0\\\">📍 Alamat:</span>\\n            <span>Kp. Cicadas, RT 05 RW 03, Desa Cadasmekar, Kec. Tegalwaru, Kab. Purwakarta, Jawa Barat, 41165</span>\\n        </li>\\n        <li class=\\\"flex items-center gap-2.5\\\">\\n            <span class=\\\"text-terra-600 dark:text-terra-400 font-bold shrink-0\\\">📞 WhatsApp / Telp:</span>\\n            <a href=\\\"https://wa.me/6281389709847\\\" target=\\\"_blank\\\" class=\\\"text-emerald-700 dark:text-emerald-400 font-bold hover:underline\\\">0813-8970-9847</a>\\n        </li>\\n        <li class=\\\"flex items-center gap-2.5\\\">\\n            <span class=\\\"text-terra-600 dark:text-terra-400 font-bold shrink-0\\\">✉️ Email:</span>\\n            <a href=\\\"mailto:abdulhamid66266@gmail.com\\\" class=\\\"text-terra-600 dark:text-terra-400 font-bold hover:underline\\\">abdulhamid66266@gmail.com</a>\\n        </li>\\n    </ul>\\n</div>\",\"bg_theme\":\"white\",\"max_width\":\"4xl\",\"alignment\":\"left\"},\"uuid\":\"afd86cbb-a915-4d6b-9ed5-e44ced7407f7\"}]',
  `meta_title` = 'Syarat & Ketentuan Transaksi - Pabrik IndoRoster Indonesia',
  `meta_description` = 'Syarat dan Ketentuan resmi transaksi pemesanan, pembayaran Midtrans, pengiriman roster beton, dan garansi ganti baru di IndoRoster Indonesia.',
  `is_active` = 1,
  `updated_at` = NOW()
WHERE `slug` = 'syarat-dan-ketentuan';

UPDATE `pages` SET 
  `title` = 'Kebijakan Privasi',
  `content` = '[{\"type\":\"rich_text\",\"data\":{\"title\":\"Kebijakan Privasi & Perlindungan Data Konsumen\",\"content\":\"<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-6\\\">\\n    Selamat datang di <strong>INDOROSTER</strong> (<em>indoroster.com</em>). Kami sangat menghargai privasi dan kepercayaan Anda sebagai pelanggan, arsitek, kontraktor, developer, maupun pengunjung situs kami. Kebijakan Privasi ini merupakan bentuk komitmen nyata kami untuk menghormati, mengamankan, dan melindungi seluruh data pribadi yang Anda percayakan kepada kami selama menggunakan layanan pabrik, bertransaksi di web, berkonsultasi via WhatsApp, maupun saat pengiriman barang ke lokasi proyek Anda.\\n</p>\\n\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-6\\\">\\n    Kebijakan ini disusun dengan mematuhi ketentuan perundang-undangan yang berlaku di Indonesia, khususnya <strong>Undang-Undang Republik Indonesia No. 27 Tahun 2022 tentang Pelindungan Data Pribadi (UU PDP)</strong> serta regulasi terkait transaksi elektronik dan perbankan digital.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">1. Dasar Hukum Pemrosesan Data Pribadi</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Pemrosesan data pribadi oleh INDOROSTER dilakukan berdasarkan landasan hukum yang sah sesuai Pasal 20 UU PDP, meliputi:\\n</p>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2 mb-4\\\">\\n    <li><strong>Persetujuan Eksplisit (Consent):</strong> Persetujuan yang Anda berikan saat mendaftar akun, mengisi formulir penawaran harga, atau memesan produk roster beton.</li>\\n    <li><strong>Kewajiban Kontraktual (Contractual Obligation):</strong> Pemrosesan data yang diperlukan untuk memenuhi kontrak pemesanan, pencetakan material, penerbitan invoice resmi, dan pengiriman kargo armada pabrik.</li>\\n    <li><strong>Kepatuhan Regulasi (Legal Compliance):</strong> Kewajiban penyimpanan arsip transaksi dan perpajakan (PPN/PPh faktur) sesuai hukum Indonesia.</li>\\n    <li><strong>Kepentingan yang Sah (Legitimate Interests):</strong> Meningkatkan performa sistem, mencegah penipuan (anti-fraud), dan menjamin mutu pelayanan pelanggan.</li>\\n</ul>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">2. Jenis Data Pribadi yang Kami Kumpulkan</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-3\\\">\\n    Kami mengumpulkan informasi yang relevan dan terbatas pada kebutuhan transaksi serta operasional, antara lain:\\n</p>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2.5 mb-4\\\">\\n    <li><strong>Data Identitas Pribadi / Perusahaan:</strong> Nama lengkap pemesan, nama penanggung jawab lapangan (mandor/arsitek/penerima barang), nama badan usaha/PT/CV (untuk pemesanan proyek/B2B), dan NPWP (opsional, untuk penerbitan Faktur Pajak).</li>\\n    <li><strong>Informasi Kontak Komunikasi:</strong> Alamat email aktif, nomor telepon genggam, dan nomor WhatsApp aktif yang digunakan untuk koordinasi pesanan serta pengiriman surat jalan digital.</li>\\n    <li><strong>Data Alamat Proyek &amp; Geografis:</strong> Alamat lengkap tujuan kirim (Provinsi, Kota/Kabupaten, Kecamatan, Kelurahan/Desa, Kode Pos, patokan jalan), catatan akses jalan armada truk (kapasitas tonase Colt Diesel/Fuso), serta titik koordinat GPS lokasi proyek jika dibagikan oleh pelanggan.</li>\\n    <li><strong>Data Riwayat Transaksi &amp; Dokumen:</strong> Rincian motif roster yang dipesan, volume/jumlah keping, riwayat pembayaran, salinan Surat Jalan (DO), Berita Acara Serah Terima (BAST), dan tanda tangan digital saat penerimaan barang.</li>\\n    <li><strong>Data Teknis &amp; Navigasi Web:</strong> Alamat Protokol Internet (IP Address), jenis browser, sistem operasi, resolusi layar, halaman yang dikunjungi, durasi sesi, dan interaksi formulir (dikumpulkan secara anonim melalui sistem analitik).</li>\\n</ul>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">3. Tujuan Penggunaan Data Pribadi</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-3\\\">\\n    Data pribadi yang terkumpul digunakan semata-mata untuk tujuan operasional dan peningkatan kepuasan pelanggan:\\n</p>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2 mb-4\\\">\\n    <li>Memvalidasi dan memproses pesanan roster beton secara akurat dari pabrik ke antrean pengiriman.</li>\\n    <li>Mengkoordinasikan jadwal keberangkatan armada truk pabrik dan kurir logistik rekanan ke alamat proyek Anda.</li>\\n    <li>Menerbitkan dokumen komersial sah meliputi Bukti Pembayaran, Faktur Komersial, Surat Jalan Pabrik, dan Resi Pelacakan Online.</li>\\n    <li>Memberikan layanan purnajual (<em>after-sales</em>), konsultasi teknis pemasangan, perhitungan volume dinding, dan klaim <strong>Garansi 100% Ganti Baru Roster Pecah</strong>.</li>\\n    <li>Mengirimkan notifikasi status pemesanan melalui WhatsApp Gateway resmi dan email transaksional otomatis.</li>\\n    <li>Mendeteksi, mencegah, dan menindaklanjuti aktivitas mencurigakan atau potensi penipuan transaksi online.</li>\\n</ul>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">4. Keamanan Transaksi &amp; Pembayaran (Midtrans Payment Gateway)</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    INDOROSTER menjunjung tinggi standar keamanan finansial tertinggi:\\n</p>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2 mb-4\\\">\\n    <li><strong>Enkripsi Jalur Komunikasi:</strong> Seluruh pertukaran data antara browser Anda dan server kami dienkripsi menggunakan protokol <strong>Transport Layer Security (TLS 1.3 / SSL 256-bit)</strong> bersertifikat resmi.</li>\\n    <li><strong>Tanpa Penyimpanan Data Finansial Sensitif:</strong> Kami <strong>tidak pernah menyimpan</strong> nomor kartu kredit lengkap, tanggal kedaluwarsa, PIN, atau kode keamanan CVV/CVC di server kami.</li>\\n    <li><strong>Sertifikasi PCI-DSS:</strong> Pemrosesan pembayaran otomatis dijalankan sepenuhnya oleh mitra gerbang pembayaran resmi <strong>PT Midtrans (Midtrans)</strong> yang telah tersertifikasi <em>PCI-DSS Level 1</em> (standar keamanan pembayaran tertinggi dunia) dan diawasi langsung oleh Bank Indonesia.</li>\\n</ul>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">5. Kerahasiaan &amp; Pembagian Data kepada Pihak Ketiga</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    INDOROSTER memiliki kebijakan <strong>Nol Toleransi terhadap Penjualan Data</strong>. Kami tidak pernah dan tidak akan pernah menjual, menyewakan, memperdagangkan, atau menyebarluaskan data pribadi Anda kepada broker data atau pihak ketiga mana pun untuk tujuan periklanan yang tidak relevan.\\n</p>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Data Anda hanya dapat dibagikan kepada pihak ketiga dalam kondisi terbatas berikut:\\n</p>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2 mb-4\\\">\\n    <li><strong>Mitra Pengemudi &amp; Logistik Ekspedisi:</strong> Pembagian nama penerima, nomor telepon kontak darurat di lokasi proyek, dan alamat pengantaran fisik semata-mata agar armada truk pengangkut dapat mengantarkan material roster tepat waktu.</li>\\n    <li><strong>Penyedia Infrastruktur Cloud &amp; Email:</strong> Layanan hosting terenkripsi dan SMTP email resmi yang terikat perjanjian kerahasiaan ketat.</li>\\n    <li><strong>Kewajiban Penegakan Hukum:</strong> Apabila diwajibkan oleh penetapan pengadilan, proses hukum perdata/pidana, atau regulasi perpajakan yang sah dari pemerintah Republik Indonesia.</li>\\n</ul>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">6. Penyimpanan &amp; Retensi Data Pribadi</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Data pribadi Anda disimpan pada server basis data yang aman dan berlokasi di pusat data bereputasi tinggi dengan perlindungan firewall bertingkat.\\n</p>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Kami menyimpan data transaksi selama akun Anda aktif atau selama jangka waktu yang diwajibkan oleh undang-undang perpajakan dan pembukuan komersial di Indonesia (minimal 5 hingga 10 tahun untuk arsip invoice dan faktur resmi). Setelah periode retensi berakhir, data non-transaksional akan dimusnahkan secara aman atau dianonimkan untuk keperluan statistik murni.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">7. Kebijakan Cookie &amp; Penyimpanan Lokal Browser</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Situs <em>indoroster.com</em> menggunakan cookie dan penyimpanan lokal (<em>local storage</em>) browser untuk keperluan teknis:\\n</p>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2 mb-4\\\">\\n    <li><strong>Cookie Fungsional Esensial:</strong> Menyimpan sesi login member yang aman, token proteksi CSRF dari serangan siber, dan item sementara di keranjang belanja.</li>\\n    <li><strong>Cookie Preferensi Pengguna:</strong> Mengingat pilihan tema tampilan visual (Mode Gelap / Terang) dan preferensi wilayah pengiriman Anda.</li>\\n    <li><strong>Analitik &amp; Kinerja:</strong> Memantau kecepatan muat halaman dan menemukan kendala tautan rusak tanpa mengidentifikasi identitas personal Anda secara langsung.</li>\\n</ul>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Anda dapat mengatur atau mematikan penggunaan cookie melalui pengaturan browser Anda, meskipun beberapa fitur belanja otomatis mungkin menjadi terbatas.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">8. Hak-Hak Pemilik Data Pribadi</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Sesuai ketentuan UU No. 27 Tahun 2022 tentang Pelindungan Data Pribadi, Anda memiliki hak penuh terhadap data pribadi Anda yang tersimpan di sistem kami:\\n</p>\\n<ul class=\\\"list-disc pl-6 text-slate-600 dark:text-slate-300 space-y-2 mb-4\\\">\\n    <li><strong>Hak Memperoleh Informasi:</strong> Mengetahui kejelasan identitas pengendali data, tujuan penggunaan, dan riwayat pemrosesan data pribadi Anda.</li>\\n    <li><strong>Hak Akses &amp; Salinan:</strong> Mendapatkan akses dan salinan data profil akun serta riwayat pesanan Anda.</li>\\n    <li><strong>Hak Pembaruan &amp; Koreksi (Rectification):</strong> Memperbarui atau memperbaiki data diri yang tidak akurat, tidak lengkap, atau sudah kedaluwarsa melalui menu Profil Member.</li>\\n    <li><strong>Hak Penghapusan &amp; Pemusnahan (Right to Erasure):</strong> Mengajukan permohonan penutupan akun dan penghapusan data pribadi Anda, sepanjang tidak bertentangan dengan kewajiban retensi arsip hukum transaksi.</li>\\n    <li><strong>Hak Menarik Persetujuan:</strong> Menolak atau menarik kembali persetujuan pemrosesan data untuk keperluan komunikasi promosi atau newsletter berkala.</li>\\n</ul>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">9. Privasi Anak di Bawah Umur</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    Layanan dan transaksi material bangunan di situs INDOROSTER ditujukan untuk pengguna yang telah cakap hukum (berusia minimal 18 tahun atau telah menikah) atau perwakilan sah dari badan usaha. Kami tidak secara sengaja mengumpulkan data pribadi dari anak-anak di bawah umur.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">10. Pembaruan Kebijakan Privasi</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-4\\\">\\n    INDOROSTER dapat meninjau dan memperbarui Kebijakan Privasi ini dari waktu ke waktu untuk menyesuaikan dengan pembaruan fitur teknologi, peningkatan standar keamanan siber, atau perubahan regulasi hukum pemerintah. Setiap revisi akan dicantumkan dengan tanggal pembaruan terbaru di halaman ini. Kami mengimbau Anda untuk memeriksa halaman ini secara berkala.\\n</p>\\n\\n<h3 class=\\\"text-xl font-bold text-slate-900 dark:text-white mt-8 mb-3\\\">11. Kontak Petugas Pelindungan Data (DPO) &amp; Bantuan Privasi</h3>\\n<p class=\\\"text-slate-600 dark:text-slate-300 leading-relaxed mb-3\\\">\\n    Apabila Anda memiliki pertanyaan, klarifikasi, keluhan, atau ingin melaksanakan hak-hak data pribadi Anda sebagaimana tercantum di atas, silakan hubungi tim resmi kami:\\n</p>\\n<div class=\\\"bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 mb-6 not-prose\\\">\\n    <p class=\\\"font-bold text-slate-900 dark:text-white text-sm mb-4\\\">PUSAT LAYANAN &amp; DATA PROTECTION INDOROSTER:</p>\\n    <ul class=\\\"space-y-3 text-xs sm:text-sm text-slate-700 dark:text-slate-300 font-medium\\\">\\n        <li class=\\\"flex items-start gap-3\\\">\\n            <span class=\\\"text-terra-600 dark:text-terra-400 font-bold shrink-0\\\">🏭 Lokasi Pabrik:</span>\\n            <span>Kp. Cicadas, RT 05 RW 03, Desa Cadasmekar, Kec. Tegalwaru, Kab. Purwakarta, Jawa Barat, 41165</span>\\n        </li>\\n        <li class=\\\"flex items-center gap-3\\\">\\n            <span class=\\\"text-terra-600 dark:text-terra-400 font-bold shrink-0\\\">📞 WhatsApp CS Pabrik:</span>\\n            <a href=\\\"https://wa.me/6281389709847\\\" target=\\\"_blank\\\" class=\\\"text-emerald-700 dark:text-emerald-400 font-bold hover:underline\\\">0813-8970-9847</a>\\n        </li>\\n        <li class=\\\"flex items-center gap-3\\\">\\n            <span class=\\\"text-terra-600 dark:text-terra-400 font-bold shrink-0\\\">✉️ Email Resmi:</span>\\n            <a href=\\\"mailto:abdulhamid66266@gmail.com\\\" class=\\\"text-terra-600 dark:text-terra-400 font-bold hover:underline\\\">abdulhamid66266@gmail.com</a>\\n        </li>\\n        <li class=\\\"flex items-center gap-3\\\">\\n            <span class=\\\"text-terra-600 dark:text-terra-400 font-bold shrink-0\\\">🌐 Website Resmi:</span>\\n            <a href=\\\"https://indoroster.com\\\" target=\\\"_blank\\\" class=\\\"text-terra-600 dark:text-terra-400 font-bold hover:underline\\\">https://indoroster.com</a>\\n        </li>\\n    </ul>\\n</div>\",\"bg_theme\":\"white\",\"max_width\":\"4xl\",\"alignment\":\"left\"},\"uuid\":\"e5d7e458-a63c-4560-9ca9-a27b0f05bb87\"}]',
  `meta_title` = 'Kebijakan Privasi & Perlindungan Data Pelanggan (UU PDP) | IndoRoster',
  `meta_description` = 'Kebijakan privasi resmi perlindungan data pribadi pelanggan, keamanan transaksi Midtrans PCI-DSS, dan kepatuhan UU PDP No. 27 Tahun 2022 di IndoRoster Indonesia.',
  `is_active` = 1,
  `updated_at` = NOW()
WHERE `slug` = 'kebijakan-privasi';

UPDATE `pages` SET 
  `title` = 'Beranda Utama (Home)',
  `content` = '[{\"type\":\"hero\",\"data\":{\"slider_duration\":5000,\"banners\":[{\"title\":\"Pabrik Roster Beton Cetak Tumbuk Padat & Siku Presisi 90°\",\"subtitle\":\"Diproduksi langsung dari sentra pengrajin Plered, Purwakarta. Formula adukan pasir silika & semen mutu K-200, hemat semen nat saat pasang, dan bergaransi pecah ganti baru 100% kirim ke seluruh Indonesia.\",\"badge\":\"🏭 Produsen Tangan Pertama · Plered, Purwakarta\",\"image\":\"https://res.cloudinary.com/indoroster/image/upload/v1765262980/2_zurmam.jpg\",\"button_text\":\"Lihat Katalog Motif\",\"button_url\":\"/katalog\",\"button_2_text\":\"Konsultasi Pabrik & Sales\",\"button_2_url\":\"https://wa.me/6281389709847\",\"alignment\":\"left\",\"image_opacity\":40,\"overlay_color\":\"#020617\",\"overlay_opacity\":80},{\"title\":\"Solusi Fasad Rumah Sejuk, Estetik & Privasi Terjaga\",\"subtitle\":\"Mereduksi panas radiasi matahari langsung (shading) sekaligus mengoptimalkan sirkulasi udara silang (cross-ventilation). Cocok untuk fasad, pagar, partisi void, dan dinding kafe industrial.\",\"badge\":\"✨ Desain Bioklimatik Tropis\",\"image\":\"https://res.cloudinary.com/indoroster/image/upload/v1765259970/7_blkgfx.jpg\",\"button_text\":\"Eksplorasi Galeri Proyek\",\"button_url\":\"/gallery\",\"button_2_text\":\"Kalkulator Kebutuhan Dinding\",\"button_2_url\":\"/kalkulator-roster\",\"alignment\":\"left\",\"image_opacity\":45,\"overlay_color\":\"#020617\",\"overlay_opacity\":85}]}},{\"type\":\"ticker\",\"data\":{\"bg_theme\":\"dark\",\"speed\":\"normal\",\"text\":\"🔥 5000+ Proyek Terpasang se-Indonesia · 🏭 Sentra Pabrikasi Plered Purwakarta · 🛡️ Garansi Pecah Ganti Baru 100% · 🚚 Kirim Rutin Tiap Hari ke Jabodetabek & Bandung · 🧱 Mutu Beton Tumbuk K-200 Sudut Siku 90°\"}},{\"type\":\"visual_showcase\",\"data\":{\"badge\":\"✨ Inspirasi Arsitektur\",\"title\":\"Tampilan Rumah Jadi 3x Lebih Mewah & Berkarakter\",\"subtitle\":\"Sentuhan roster beton arsitektural menghadirkan permainan bayangan cahaya matahari alami yang dramatis sekaligus menjaga rumah tetap adem sepanjang hari.\",\"bg_theme\":\"slate\"}},{\"type\":\"strength_test\",\"data\":{\"badge\":\"💪 Uji Ketahanan Material K-200\",\"title\":\"Seberapa Kuat Roster Beton IndoRoster?\",\"subtitle\":\"Bukan cetak basah rapuh yang mudah rompal di jalan. Kami menggunakan teknik cetak tumbuk padat hidrolik dengan densitas tinggi—menghasilkan keping roster padat, tahan benturan, minim porositas, dan tahan terpaan cuaca luar puluhan tahun.\",\"bg_theme\":\"dark\"}},{\"type\":\"featured_products\",\"data\":{\"badge\":\"🏆 #1 Pilihan Arsitek & Pemborong\",\"title\":\"Motif Roster Best Seller Bulan Ini\",\"subtitle\":\"Deretan motif roster beton minimalis terfavorit dengan tingkat kepresisian tinggi, stok produksi siap suplai, dan paling banyak dipasang untuk pagar serta dinding fasad.\",\"grid_columns\":\"6\",\"limit\":8,\"bg_theme\":\"white\"}},{\"type\":\"viral_products\",\"data\":{\"badge\":\"🔥 Paling Dicari Pemilik Rumah\",\"title\":\"Produk Viral & Paling Banyak Dibeli\",\"subtitle\":\"Koleksi motif roster arsitektural modern yang sedang tren di media sosial dan banyak diaplikasikan pada hunian bertema Japandi, Industrial, dan Tropis Modern.\",\"limit\":6,\"bg_theme\":\"white\"}},{\"type\":\"why_us\",\"data\":{\"badge\":\"💎 Standar Mutu Lapangan\",\"title\":\"Kenapa Tukang & Arsitek Memilih IndoRoster?\",\"description\":\"Kami adalah produsen langsung di sentra Plered Purwakarta yang mengerti kebutuhan teknis lapangan: dimensi presisi agar tukang hemat semen adukan, dan pasokan aman tanpa risiko mandek di tengah proyek.\",\"bg_theme\":\"slate\",\"items\":[{\"title\":\"Akurasi Siku 90° & Cetak Tumbuk Padat\",\"description\":\"Setiap keping dicetak padat presisi. Tukang di lapangan tidak perlu repot meratakan adukan semen nat tebal-tipis, sehingga dinding cepat berdiri rapi dan hemat ongkos tukang.\"},{\"title\":\"Murni Pabrik Tangan Pertama (Tanpa Perantara)\",\"description\":\"Harga langsung dari sentra produksi Plered. Melayani pembelian eceran puluhan pcs untuk renovasi rumah hingga volume ribuan keping untuk pengadaan proyek komersial & perumahan.\"},{\"title\":\"Garansi Pecah Ganti Baru 100% di Tempat\",\"description\":\"Jika ada unit yang retak atau pecah saat dibongkar dari truk di lokasi proyek Anda, cukup foto Surat Jalan dan kami ganti unit baru secara gratis.\"}]}},{\"type\":\"shipping_info\",\"data\":{\"badge\":\"🚚 Armada Logistik Pabrik\",\"title\":\"Jangkauan Pengiriman Seluruh Indonesia\",\"subtitle\":\"Pusat Suplai Roster Beton Murah Jabodetabek (Jakarta, Bogor, Depok, Tangerang, Bekasi), Bandung, Cianjur, Sukabumi, Karawang, Cirebon, hingga Ekspedisi Kargo ke Luar Jawa.\",\"bg_theme\":\"dark\"}},{\"type\":\"document_procurement_proof\",\"data\":{\"badge\":\"📑 Dokumen Pengadaan Lengkap\",\"title\":\"Kesiapan Administrasi Sah & Faktur Pajak Resmi\",\"subtitle\":\"Surat Jalan (DO) berstempel resmi pabrik, Invoice Komersial, Faktur Pajak PPN/PPh resmi, dan SPK siap kami terbitkan cepat untuk kebutuhan administrasi proyek kontraktor & developer.\",\"bg_theme\":\"white\"}},{\"type\":\"scanned_document_gallery\",\"data\":{\"badge\":\"📸 Bukti Nyata Transaksi Lapangan\",\"title\":\"Galeri Foto Scan Dokumen & Bukti Pengiriman Harian\",\"subtitle\":\"Transparansi pengiriman harian armada truk pabrik dan tanda terima bertandatangan asli dari para mandor dan pemilik proyek di berbagai kota.\",\"bg_theme\":\"slate\"}},{\"type\":\"social_review\",\"data\":{\"badge\":\"📱 Viral on TikTok\",\"title\":\"Lihat Langsung Review Para Kreator Dekorasi Rumah\",\"subtitle\":\"Dengarkan ulasan jujur dari kreator renovasi rumah dan desainer tentang kepadatan beton, kerapian sudut, dan hasil estetika roster kami setelah terpasang di dinding.\",\"bg_theme\":\"dark\"}},{\"type\":\"testimonials\",\"data\":{\"badge\":\"⭐ Pengalaman Pembeli Nyata\",\"title\":\"Kata Pelanggan & Pemilik Rumah\",\"subtitle\":\"Kepuasan para pemilik hunian pribadi, arsitek, dan kontraktor yang telah merasakan langsung kualitas produk dan ketepatan jadwal kirim armada kami.\",\"bg_theme\":\"white\"}},{\"type\":\"gallery_grid\",\"data\":{\"badge\":\"🏛️ Dokumentasi Proyek Nyata\",\"title\":\"Proyek yang Berbicara: Sebelum & Sesudah Terpasang\",\"subtitle\":\"Inspirasi pemasangan roster beton minimalis pada fasad rumah tinggal, pagar pembatas, sekat interior void, hingga kafe kekinian di berbagai wilayah.\",\"bg_theme\":\"dark\"}},{\"type\":\"ugc_videos\",\"data\":{\"badge\":\"🎬 Visual Experience Video\",\"title\":\"Lihat Detail Aliran Angin & Pencahayaan Lebih Dekat\",\"subtitle\":\"Koleksi video estetika celah geometris roster beton: bagaimana udara segar mengalir lancar dan pencahayaan alami mempercantik sudut ruangan.\",\"bg_theme\":\"white\"}},{\"type\":\"partner_cta\",\"data\":{\"badge\":\"🔥 Konsultasi Gratis & Hitung Kebutuhan\",\"title\":\"Wujudkan Dinding Fasad Estetik Impian Anda Sekarang\",\"description\":\"Diskusikan pilihan motif, luas bidang dinding (m2), dan dapatkan estimasi ongkos kirim armada pabrik termurah langsung dari tim sales resmi IndoRoster.\",\"bg_theme\":\"terra\",\"cta_text_1\":\"Konsultasi via WhatsApp (Fast Response)\",\"cta_url_1\":\"https://wa.me/6281389709847\",\"cta_text_2\":\"Lihat Katalog Lengkap Dahulu\",\"cta_url_2\":\"/katalog\"}},{\"type\":\"faq\",\"data\":{\"badge\":\"❓ Panduan & Tanya Jawab Lengkap\",\"title\":\"Pertanyaan yang Sering Diajukan Seputar Roster Beton\",\"subtitle\":\"Informasi praktis seputar dimensi ukuran (20x20 cm), cara menghitung kebutuhan (25 pcs/m2), teknik pasang nat presisi, dan jaminan keamanan kirim armada pabrik.\",\"bg_theme\":\"white\"}}]',
  `meta_title` = 'Pabrik Roster Beton Minimalis | Supplier Proyek Kirim Jabodetabek, Bandung & Seluruh Indonesia — IndoRoster',
